use std::{
    env, fs, io,
    path::Path,
    process::{Command, Output},
    time::Duration,
};

use anyhow::{Context, Result, anyhow, bail};
use url::Url;

use crate::project::Project;

const DEFAULT_REDIS_URL: &str = "redis://127.0.0.1:6379/";
const COMPOSE_RELATIVE: &str = ".toolbox/redis/compose.yaml";
const GENERATED_HEADER: &str =
    "# Generated by devtoolbox. Re-run with --force to replace local edits.\n";

pub fn installed(project: &Project) -> bool {
    project.root().join(COMPOSE_RELATIVE).is_file()
}

pub fn add(project: &Project, dry_run: bool, force: bool) -> Result<()> {
    let compose_path = project.root().join(COMPOSE_RELATIVE);
    let compose_content = format!("{GENERATED_HEADER}{COMPOSE}");
    let env_path = project.root().join(".env.example");
    let env_content = merge_env(&read_optional(&env_path)?)?;

    println!("Projet Rust détecté : {}", project.root().display());
    println!(
        "  {:>9}  {}",
        change_kind(&compose_path, &compose_content)?,
        relative_display(project.root(), &compose_path)
    );
    println!(
        "  {:>9}  {}",
        change_kind(&env_path, &env_content)?,
        relative_display(project.root(), &env_path)
    );

    if dry_run {
        println!("Dry-run : aucun fichier modifié.");
        return Ok(());
    }

    if compose_path.is_file() {
        let existing = fs::read_to_string(&compose_path)
            .with_context(|| format!("lecture de {}", compose_path.display()))?;
        if existing != compose_content && !force {
            bail!(
                "{} existe et diffère du contenu généré ; utilisez --force après revue",
                relative_display(project.root(), &compose_path)
            );
        }
    }

    write_if_changed(&compose_path, &compose_content)?;
    write_if_changed(&env_path, &env_content)?;
    println!("Redis ajouté. Étape suivante : toolbox up");
    Ok(())
}

pub fn up(project: &Project) -> Result<()> {
    ensure_generated(project)?;
    let redis_url = connection_url()?;
    let parsed = parse_url(&redis_url)?;
    if !is_local(&parsed) {
        bail!(
            "toolbox up démarre uniquement le provider local ; utilisez toolbox doctor redis pour tester un REDIS_URL distant"
        );
    }

    let mut command = compose_command(project);
    command.args(["up", "-d", "--wait", "--wait-timeout", "60", "redis"]);
    println!("Démarrage de Redis…");
    let output = run_output(&mut command, "docker compose up")?;
    ensure_success(&output, "le démarrage de Redis")?;
    ping(&redis_url)?;
    println!("Redis est healthy et répond à PING.");
    Ok(())
}

pub fn doctor(project: &Project) -> Result<()> {
    let redis_url = connection_url()?;
    let parsed = parse_url(&redis_url)?;
    let local = is_local(&parsed);
    let mut failed = false;

    println!("Diagnostic Redis");
    report(installed(project), "câblage toolbox présent", &mut failed);
    println!("  [info] endpoint {}", safe_endpoint(&parsed));
    println!(
        "  [info] provider {}",
        if local { "local" } else { "distant" }
    );

    if local {
        let docker_ok = check_command(&mut docker_version_command());
        report(docker_ok, "CLI et daemon Docker accessibles", &mut failed);
        if docker_ok && installed(project) {
            report(
                check_command(&mut compose_config_command(project)),
                "configuration Compose valide",
                &mut failed,
            );
            report(
                check_command(&mut redis_ping_command(project)),
                "conteneur Redis actif et répondant",
                &mut failed,
            );
        }
    } else {
        println!("  [skip] Docker ignoré pour un provider distant");
    }

    match ping(&redis_url) {
        Ok(()) => report(true, "commande Redis PING → PONG", &mut failed),
        Err(error) => report(
            false,
            &format!("commande Redis PING : {error:#}"),
            &mut failed,
        ),
    }

    if failed {
        bail!("diagnostic en échec ; corrigez les lignes [fail] ci-dessus")
    }
    println!("Diagnostic terminé sans erreur.");
    Ok(())
}

pub fn down(project: &Project) -> Result<()> {
    ensure_generated(project)?;
    let mut command = compose_command(project);
    command.arg("down");
    let output = run_output(&mut command, "docker compose down")?;
    ensure_success(&output, "l'arrêt de Redis")?;
    println!("Redis arrêté ; le volume de données est conservé.");
    Ok(())
}

fn connection_url() -> Result<String> {
    Ok(env::var("REDIS_URL").unwrap_or_else(|_| DEFAULT_REDIS_URL.to_owned()))
}

fn parse_url(redis_url: &str) -> Result<Url> {
    let parsed = Url::parse(redis_url).context("REDIS_URL n'est pas une URL valide")?;
    if matches!(parsed.scheme(), "redis" | "rediss") {
        Ok(parsed)
    } else {
        bail!("REDIS_URL doit utiliser redis:// ou rediss://")
    }
}

fn ping(redis_url: &str) -> Result<()> {
    let client = redis::Client::open(redis_url).context("configuration du client Redis")?;
    let mut connection = client
        .get_connection_with_timeout(Duration::from_secs(3))
        .context("connexion Redis")?;
    let response: String = redis::cmd("PING")
        .query(&mut connection)
        .context("PING Redis")?;
    if response != "PONG" {
        bail!("réponse inattendue : {response}")
    }
    Ok(())
}

fn compose_command(project: &Project) -> Command {
    let mut command = Command::new("docker");
    command
        .arg("compose")
        .arg("-p")
        .arg(format!("{}-redis", project.compose_project_name()))
        .arg("-f")
        .arg(project.root().join(COMPOSE_RELATIVE));
    command
}

fn docker_version_command() -> Command {
    let mut command = Command::new("docker");
    command.args(["info", "--format", "{{.ServerVersion}}"]);
    command
}

fn compose_config_command(project: &Project) -> Command {
    let mut command = compose_command(project);
    command.args(["config", "--quiet"]);
    command
}

fn redis_ping_command(project: &Project) -> Command {
    let mut command = compose_command(project);
    command.args(["exec", "-T", "redis", "redis-cli", "ping"]);
    command
}

fn check_command(command: &mut Command) -> bool {
    command
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .is_ok_and(|status| status.success())
}

fn run_output(command: &mut Command, label: &str) -> Result<Output> {
    command
        .output()
        .with_context(|| format!("impossible d'exécuter {label}"))
}

fn ensure_success(output: &Output, label: &str) -> Result<()> {
    if output.status.success() {
        return Ok(());
    }
    let stderr = String::from_utf8_lossy(&output.stderr);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let details = if stderr.trim().is_empty() {
        stdout.trim()
    } else {
        stderr.trim()
    };
    bail!("{label} a échoué : {details}")
}

fn ensure_generated(project: &Project) -> Result<()> {
    let path = project.root().join(COMPOSE_RELATIVE);
    if !path.is_file() {
        bail!("{} manque ; exécutez toolbox add redis", path.display());
    }
    Ok(())
}

fn is_local(url: &Url) -> bool {
    matches!(url.host_str(), Some("127.0.0.1" | "localhost" | "::1"))
}

fn safe_endpoint(url: &Url) -> String {
    let host = url.host_str().unwrap_or("<hôte manquant>");
    let port = url
        .port()
        .unwrap_or(if url.scheme() == "rediss" { 6380 } else { 6379 });
    format!("{}://{host}:{port}{}", url.scheme(), url.path())
}

fn report(ok: bool, message: &str, failed: &mut bool) {
    if ok {
        println!("  [ok]   {message}");
    } else {
        println!("  [fail] {message}");
        *failed = true;
    }
}

fn merge_env(existing: &str) -> Result<String> {
    let base = strip_managed_block(existing, "redis")?;
    if contains_assignment(existing, "REDIS_URL") {
        return Ok(existing.to_owned());
    }
    let body = format!("REDIS_URL={DEFAULT_REDIS_URL}");
    append_managed_block(&base, "redis", &body)
}

fn strip_managed_block(existing: &str, label: &str) -> Result<String> {
    let start_marker = format!("# >>> devtoolbox:{label}");
    let end_marker = format!("# <<< devtoolbox:{label}");
    let Some(start) = existing.find(&start_marker) else {
        return Ok(existing.to_owned());
    };
    let relative_end = existing[start..]
        .find(&end_marker)
        .ok_or_else(|| anyhow!("bloc {label} incomplet : marqueur de fin absent"))?;
    let end = start + relative_end + end_marker.len();
    let mut base = String::new();
    base.push_str(existing[..start].trim_end_matches('\n'));
    if !base.is_empty() && !existing[end..].trim().is_empty() {
        base.push('\n');
    }
    base.push_str(existing[end..].trim_start_matches('\n'));
    Ok(base)
}

fn append_managed_block(base: &str, label: &str, body: &str) -> Result<String> {
    if body.is_empty() {
        let mut output = base.trim_end_matches('\n').to_owned();
        if !output.is_empty() {
            output.push('\n');
        }
        return Ok(output);
    }
    let mut output = base.trim_end_matches('\n').to_owned();
    if !output.is_empty() {
        output.push_str("\n\n");
    }
    output.push_str(&format!(
        "# >>> devtoolbox:{label}\n{body}\n# <<< devtoolbox:{label}\n"
    ));
    Ok(output)
}

fn contains_assignment(content: &str, key: &str) -> bool {
    content.lines().any(|line| {
        line.trim_start()
            .strip_prefix(key)
            .is_some_and(|suffix| suffix.trim_start().starts_with('='))
    })
}

fn read_optional(path: &Path) -> Result<String> {
    match fs::read_to_string(path) {
        Ok(content) => Ok(content),
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(String::new()),
        Err(error) => Err(error).with_context(|| format!("lecture de {}", path.display())),
    }
}

fn change_kind(path: &Path, desired: &str) -> Result<&'static str> {
    if !path.exists() {
        return Ok("create");
    }
    let current =
        fs::read_to_string(path).with_context(|| format!("lecture de {}", path.display()))?;
    if current == desired {
        Ok("unchanged")
    } else {
        Ok("update")
    }
}

fn write_if_changed(path: &Path, content: &str) -> Result<()> {
    if path.is_file() && fs::read_to_string(path)? == content {
        return Ok(());
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).with_context(|| format!("création de {}", parent.display()))?;
    }
    fs::write(path, content).with_context(|| format!("écriture de {}", path.display()))
}

fn relative_display(root: &Path, path: &Path) -> String {
    path.strip_prefix(root)
        .unwrap_or(path)
        .display()
        .to_string()
}

const COMPOSE: &str = r#"services:
  redis:
    image: redis:8.8.1-alpine@sha256:8096655e437712b07503796fb64d81359256cfcff0ab29d95a7da72863786efb
    command: ["redis-server", "--appendonly", "yes"]
    ports:
      - "127.0.0.1:${TOOLBOX_REDIS_PORT:-6379}:6379"
    volumes:
      - redis-data:/data
    healthcheck:
      test: ["CMD", "redis-cli", "ping"]
      interval: 2s
      timeout: 3s
      retries: 30
      start_period: 5s

volumes:
  redis-data:
"#;

#[cfg(test)]
mod tests {
    use super::{is_local, merge_env, strip_managed_block};
    use url::Url;

    #[test]
    fn merge_env_is_idempotent() {
        let once = merge_env("APP_ENV=dev\n").unwrap();
        assert_eq!(once, merge_env(&once).unwrap());
        assert_eq!(once.matches("REDIS_URL=").count(), 1);
    }

    #[test]
    fn existing_redis_url_is_preserved() {
        let merged = merge_env("REDIS_URL=rediss://cache.example/\n").unwrap();
        assert!(merged.contains("REDIS_URL=rediss://cache.example/"));
        assert_eq!(merged.matches("REDIS_URL=").count(), 1);
    }

    #[test]
    fn malformed_managed_block_is_rejected() {
        assert!(strip_managed_block("# >>> devtoolbox:redis\nvalue", "redis").is_err());
    }

    #[test]
    fn classifies_loopback_as_local() {
        assert!(is_local(&Url::parse("redis://127.0.0.1:6379/").unwrap()));
        assert!(!is_local(&Url::parse("rediss://cache.example/").unwrap()));
    }
}
